/* Struct Layouts */
struct Any {
    const char* _type_name;
    void** _vtable;
};

struct Loadable {
    const char* _type_name;
    void** _vtable;
};

struct Stringable {
    const char* _type_name;
    void** _vtable;
};

struct Class {
    const char* _type_name;
    void** _vtable;
};

struct Introspection {
    const char* _type_name;
    void** _vtable;
};

struct Enum {
    const char* _type_name;
    void** _vtable;
};

struct Buf {
    const char* _type_name;
    void** _vtable;
};

struct Conditional {
    const char* _type_name;
    void** _vtable;
};

struct Dir {
    const char* _type_name;
    void** _vtable;
};

